const query =
  $input.first().json.query ||
  $input.first().json.input ||
  "";

const knowledgeBase = [
  {
    topic: "AI Agents",
    content:
      "An AI agent is a goal-driven system that can reason about a task, choose available tools, perform actions, observe results, and generate a response. An agent is not just a chatbot because it can have instructions, tools, memory, context, boundaries, and decision capability."
  },
  {
    topic: "Standard Workflow",
    content:
      "A standard workflow follows a fixed predefined sequence of steps. For example: Trigger, Validate Data, Process Data, Store Result, Send Notification. Unlike an AI agent, it does not dynamically choose tools based on a goal."
  },
  {
    topic: "AI Agent Tools",
    content:
      "Common AI agent tools include searching a knowledge base, reading Google Sheets, querying a database, calling an API, sending an email, and creating a support ticket."
  },
  {
    topic: "Memory",
    content:
      "Conversation memory allows an AI agent to retain relevant information from earlier turns in the same conversation. This helps the agent understand follow-up questions without requiring the user to repeat previous information."
  },
  {
    topic: "Structured AI Output",
    content:
      "Structured AI output makes an AI model return predictable data such as JSON. In the internship support triage project, the target fields included category, priority, sentiment, department, summary, and suggested response."
  },
  {
    topic: "Customer Support Triage",
    content:
      "The AI Customer Support Triage System receives a customer message and uses AI to determine category, priority, sentiment, department, summary, and suggested response. The workflow can then route the ticket and send notifications."
  },
  {
    topic: "RAG",
    content:
      "Retrieval-Augmented Generation, or RAG, allows an AI system to retrieve relevant information from external knowledge before generating an answer. A typical RAG process is Documents, Extraction, Chunking, Embeddings, Vector Database, Retrieval, and AI Response."
  },
  {
    topic: "Embeddings",
    content:
      "Embeddings are numerical representations of text that allow similar pieces of information to be found using semantic similarity. They are commonly used in vector databases for RAG systems."
  },
  {
    topic: "n8n AI Automation",
    content:
      "n8n can be used to build AI automation workflows by connecting triggers, AI models, agents, memory, APIs, databases, and other tools. AI Agent nodes can choose from connected tools based on their instructions and the user's request."
  }
];

const searchTerms = query
  .toLowerCase()
  .split(/\s+/)
  .filter(word => word.length > 2);

const results = knowledgeBase.filter(item => {
  const searchableText =
    `${item.topic} ${item.content}`.toLowerCase();

  return searchTerms.some(term =>
    searchableText.includes(term)
  );
});

if (results.length === 0) {
  return [
    {
      json: {
        result:
          "No relevant information was found in the knowledge base."
      }
    }
  ];
}

return [
  {
    json: {
      result: results
        .map(item => `${item.topic}: ${item.content}`)
        .join("\n\n")
    }
  }
];
